    s_saleConfig.referrerFeeOnTokensSoldBps = _saleInitParams.referrerFeeOnTokensSoldBps;
    s_saleConfig.minimumInvestAmount = _saleInitParams.minimumInvestAmount;

    // Set the address configuration
